import { z, type ZodType } from "zod";

/**
 * API contracts (D1, docs/DOCS-PLAN.md). Every HTTP route OPEX serves has one contract, next to its
 * handler. Handlers parse requests with the contract's own schemas, so the published OpenAPI
 * (generated by `pnpm docs:api`) cannot disagree with the code. A test fails when a registered route
 * has no contract (or a contract has no route); D2 checks every response the tests receive against
 * the documented response schema.
 */

export type Audience = "partner" | "oauth" | "manage" | "delivery" | "render" | "ops" | "site";
/** How the caller authenticates. */
export type AuthKind =
  | "none"
  | "session" // console cookie (+ CSRF header on writes)
  | "partner" // OAuth 2.1 access token, DPoP-bound (AraCMS)
  | "delivery" // Bearer DELIVERY_TOKEN (the website)
  | "render" // Bearer RENDER_TOKEN (the 3D renderer)
  | "metrics" // Bearer METRICS_TOKEN (Prometheus)
  | "preview" // opex-preview header: a signed preview token
  | "client"; // OAuth client authentication (private_key_jwt)
export type Role = "viewer" | "auditor" | "operator" | "super_admin";

export type ResponseSpec = {
  description: string;
  /** JSON body schema (omit for an empty body). */
  schema?: ZodType;
  contentType?: string;
  headers?: Record<string, string>;
  example?: unknown;
};
export type ErrorSpec = { status: number; code: string; when: string };

export type RouteContract = {
  /** Stable operationId (camelCase). */
  id: string;
  method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
  /** Fastify path (`/v1/manage/forms/:id`). */
  path: string;
  audience: Audience;
  tags: string[];
  summary: string;
  description?: string;
  auth: AuthKind;
  /** Lowest console role allowed (session routes). Auditors never pass write routes. */
  role?: Role;
  /** Only these roles (overrides `role`). */
  roles?: Role[];
  /** Needs a fresh second factor (5 minutes). */
  stepUp?: boolean;
  params?: z.ZodObject;
  query?: z.ZodObject;
  body?: ZodType;
  /** Body media type (default application/json when `body` is set). */
  bodyType?: "application/json" | "application/octet-stream" | "multipart/form-data" | "application/x-www-form-urlencoded";
  headers?: { name: string; required?: boolean; description: string }[];
  responses: Record<number, ResponseSpec>;
  /** Route-specific errors (generic ones — validation, auth, CSRF, rate limit — are added for you). */
  errors?: ErrorSpec[];
  /** "N per minute per IP" etc., when it differs from the global 600/min. */
  rateLimit?: string;
  /** Partner writes: Idempotency-Key + RFC 9421 signature. */
  signed?: boolean;
  /** Audit actions this route records (no personal data in any of them). */
  audit?: string[];
  requestExample?: unknown;
  /** Source file (relative to apps/opex-api/src, or a repo path starting with apps/), for readers and the docs-impact check. */
  source: string;
};

export const route = <T extends RouteContract>(c: T): T => c;

// ── Shared schemas ──
export const Iso = z.iso.datetime({ offset: true }).describe("ISO 8601 timestamp");
export const IsoOrNull = Iso.nullable();
export const Id = (prefix: string, example?: string) => z.string().max(40).describe(`Identifier (${prefix}…)`).meta(example ? { examples: [example] } : {});
export const Ok = z.object({ ok: z.literal(true) });
export const Locale = z.enum(["fa", "en", "tr"]);
export const Localized = z.object({ fa: z.string().optional(), en: z.string().optional(), tr: z.string().optional() }).describe("A value per locale; missing locales fall back (tr → en → fa).");

/** RFC 9457 problem details (application/problem+json). `code` is stable; `detail` is for humans. */
export const ProblemSchema = z
  .object({
    type: z.string().optional(),
    title: z.string(),
    status: z.number().int(),
    code: z.string().describe("Stable machine code, e.g. VALIDATION_FAILED, CONFLICT_BASE_REVISION."),
    detail: z.string().optional(),
    instance: z.string().describe("The request id (also in the X-Request-Id header)."),
    issues: z.array(z.object({ path: z.string(), message: z.string() })).optional().describe("Field problems, for VALIDATION_FAILED and form submissions."),
  })
  .loose()
  .meta({ id: "Problem" });
